children.command:
$Scan = Repair-WindowsImage -Online -ScanHealth
if ($Scan.ImageHealthState -eq "Healthy") {
  Write-Host "Healthy. Running SFC." -ForegroundColor Green
} else {
  Write-Host "Corruption found! Restoring..." -ForegroundColor Red
  Repair-WindowsImage -Online -RestoreHealth
}
sfc /scannow
